import {Radio, RadioGroup, FormControl, Button} from '@primer/react'
import {useState, type ChangeEvent} from 'react'
import styles from './PlatformSelector.module.css'
import type {FieldProgressionFieldEditComponentProps} from './FieldProgressionField'
import {type Platform, getAvailablePlatforms} from '../../../types/platform'
import {PlatformIcon} from './PlatformIcon'

interface IProps extends FieldProgressionFieldEditComponentProps<Platform> {
  isMacosInRunnerGroupsEnabled: boolean
  isCustomImageUploadingEnabled: boolean
  onValidationError: (error: boolean) => void
}

export function PlatformSelector({
  isMacosInRunnerGroupsEnabled,
  isCustomImageUploadingEnabled,
  onSave,
  onValidationError,
  setValue,
  value,
}: IProps) {
  const availablePlatforms = getAvailablePlatforms(isMacosInRunnerGroupsEnabled)
  const [editorValue, setEditorValue] = useState<Platform | null>(value || availablePlatforms[0] || null)

  const handleInputChange = (selected: string | null, e: React.ChangeEvent<HTMLInputElement> | undefined) => {
    if (e) {
      const selectedPlatform = availablePlatforms.find(option => option.id === selected)
      setEditorValue(selectedPlatform || null)
    }
  }

  const handleSave = () => {
    onValidationError(false)
    if (!editorValue) {
      onValidationError(true)
      return
    }

    setValue(editorValue)
    if (onSave) {
      onSave()
    }
  }

  const availableOptions = availablePlatforms.filter(option => {
    const isCustomPlatform = option.id === 'custom'

    return isCustomImageUploadingEnabled || !isCustomPlatform
  })

  return (
    <>
      <div className={styles.platformInput} data-testid="platform-input">
        <RadioGroup
          name={'platformRadioGroup'}
          onChange={(selected, e: ChangeEvent<HTMLInputElement> | undefined) => {
            handleInputChange(selected, e)
          }}
        >
          <RadioGroup.Label visuallyHidden>Platform</RadioGroup.Label>
          {availableOptions.map(option => (
            <FormControl key={option.id}>
              <Radio
                value={option.id}
                checked={option === editorValue}
                data-testid={`platform-option-radio-${option.id}`}
              />
              <FormControl.Label className={styles.normalWeight} data-testid={`platform-option-label-${option.id}`}>
                <PlatformIcon osType={option.osType} className="mr-2 color-fg-muted" />
                {option.displayName}
              </FormControl.Label>
            </FormControl>
          ))}
        </RadioGroup>
      </div>
      <div className={styles.saveButtonContainer}>
        <Button className={styles.saveButton} onClick={handleSave} data-testid="platform-save-button">
          Save
        </Button>
      </div>
    </>
  )
}
